     public static func routeFixtures() -> [String: Data] {
        // 真实路线 quye-141「长海子」，数据来自远端 walkbg 公开路线 API（无鉴权可读的轨迹/海拔/图片）。
        let routeId = "quye-141"
        let summary = """
        {"routeId":"\(routeId)","currentVersionId":"\(routeId)-v1","cover":"https://qiniu.quye.fun/prod/2026/07/23/6900ada4d0354dcca811ab7ec43b45b3.jpg","name":"长海子","region":"四川省甘孜藏族自治州","difficulty":"2.48","distance":{"meters":12378.12},"ascent":{"meters":434.0},"estimatedDuration":{"seconds":19620.0}}
        """
        let browse = Data("{\"data\":{\"items\":[\(summary)]}}".utf8)
        let search = Data("{\"data\":{\"state\":\"completed\",\"items\":[\(summary)]}}".utf8)
        let initialSearch = Data("{\"data\":{\"state\":\"initial\",\"items\":[]}}".utf8)
        var fixtures: [String: Data] = [
            PublicRouteAPI.Featured().identifier: browse,
            PublicRouteAPI.All().identifier: browse,
            PublicRouteAPI.Search(query: "长海子").identifier: search,
            PublicRouteAPI.Search(query: nil).identifier: initialSearch,
        ]

        fixtures[PublicRouteAPI.Detail(id: routeId).identifier] = publicRouteDetailData()
        return fixtures
    }

